import java.util.*;
public class Abood2D {
	static int N, fifty, hundred, K;
	static int[][][] memo;
	static int[][][][] memo2;
	static final int MOD = (int) 1e9 + 7;
	static long[][] comb;

	static int solve(int t, int f, int h) {
		if (f + h == 0) return 0;
		if (memo[t][f][h] != -1) return memo[t][f][h];
		if (t == 1) return 1 + (f < fifty ? solve(0, f + 1, h) : solve(0, f, h + 1));
		int answer = (int) 1e6;
		for (int i = 0; i <= f; i++) {
			if (i * 50 > K) break;
			int j = Math.min((K - i * 50) / 100, h);
			int totalWeight = i * 50 + j * 100;
			if ((fifty - f + i > 0 && totalWeight > 50) || (hundred - h + j > 1 && totalWeight > 100) || (i == fifty && j == hundred))
				answer = Math.min(answer, solve(1, f - i, h - j));
		}
		return memo[t][f][h] = answer + 1;
	}

	static int solve2(int t, int f, int h, int r) {
		if (r == 0 && f == 0 && h == 0) return 1;
		if (r == 0) return 0;
		if (memo2[t][f][h][r] != -1) return memo2[t][f][h][r];
		int res = 0;
		if (t == 1) {
			for (int i = 0; i <= fifty - f; i++) {
				if (i * 50 > K) break;
				for (int j = 0; j <= hundred - h; j++) {
					if (i == 0 && j == 0) continue;
					int weightSum = i * 50 + j * 100;
					if (weightSum > K) break;
					res = (int) ((res + (long) (nCk(fifty - f, i) * nCk(hundred - h, j) % MOD) * solve2(0, f + i, h + j, r - 1)) % MOD);
				}
			}
		} else {
			for (int i = 0; i <= f; i++) {
				if (i * 50 > K) break;
				for (int j = 0; j <= h; j++) {
					if (i == 0 && j == 0) continue;
					int weightSum = i * 50 + j * 100;
					if (weightSum > K) break;
					res = (int) ((res + (long) (nCk(f, i) * nCk(h, j) % MOD) * solve2(1, f - i, h - j, r - 1)) % MOD);
				}
			}
		}
		return memo2[t][f][h][r] = res;
	}

	static long nCk(int n, int k) {
		if (n < k) return 0;
		if (k == 0 || n == k) return 1;
		if (comb[n][k] != -1) return comb[n][k];
		if (n - k < k) return comb[n][k] = nCk(n, n - k);
		return comb[n][k] = (((long) n * nCk(n - 1, k - 1)) * pow(k, MOD - 2)) % MOD;
	}

	static int pow(int x, long p) {
		int result = 1;
		while (p > 0) {
			if ((p & 1) == 1)
				result = (int) ((long) result * x % MOD);
			x = (int) ((long) x * x % MOD);
			p >>= 1;
		}
		return result;
	}

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		int totalItems = sc.nextInt();
		K = sc.nextInt();
		int[] items = new int[totalItems];
		for (int i = 0; i < totalItems; i++) items[i] = sc.nextInt();
		for (int v : items) {
			if (v == 50) fifty++;
			else if (v == 100) hundred++;
		}
		memo = new int[2][fifty + 1][hundred + 1];
		for (int i = 0; i < 2; i++)
			for (int j = 0; j <= fifty; j++)
				Arrays.fill(memo[i][j], -1);
		comb = new long[101][101];
		for (int i = 0; i <= 100; i++)
			Arrays.fill(comb[i], -1);
		int minSteps = solve(0, fifty, hundred);
		if (minSteps >= (int) 1e6) {
			System.out.println(-1);
			System.out.println(0);
		} else {
			memo2 = new int[2][fifty + 1][hundred + 1][minSteps + 1];
			for (int i = 0; i < 2; i++)
				for (int j = 0; j <= fifty; j++)
					for (int j2 = 0; j2 <= hundred; j2++)
						Arrays.fill(memo2[i][j][j2], -1);
			System.out.println(minSteps);
			System.out.println(solve2(0, fifty, hundred, minSteps));
		}
	}
}
